  reset:'M3 10a9 9 0 1 1 2 8 M3 4v6h6',
  help:'M9.5 8a2.6 2.6 0 0 1 5 1c0 2-2.5 2-2.5 4 M12 17h.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
