  menu:'M4 6h16 M4 12h16 M4 18h16',
  clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0',
  leaf:'M20 3C7 2 2 8 5 15s15 5 15-12z M4 21 16 8',
  wallet:'M3 6h17v15H3V6z M3 6V3h14v3 M15 11h7v6h-7v-6z M18 14h.01',
